// ddHello.cpp : Defines the entry point for the application.
//
#include "stdafx.h"
#include "resource.h"
#include <ddraw.h>
#define MAX_LOADSTRING 100
// Global Variables:
HINSTANCE hInst;
HWND hwnd;
TCHAR szTitle[MAX_LOADSTRING];
TCHAR szWindowClass[MAX_LOADSTRING];

LPDIRECTDRAW lpDD;
LPDIRECTDRAWSURFACE lpDDSPrimary;
LPDIRECTDRAWSURFACE lpDDSBackSurf;
LPDIRECTDRAWCLIPPER lpClipper;
RECT lprcBack;//=NULL;
RECT lprcPrimary;//=NULL;
DDBLTFX  ddbltfx;

char szMsg1[] = "Hello World, I am DirectDraw boy !";
char szMsg2[] = "Press ESC exit";

// Foward declarations of functions included in this code module:
ATOM                MyRegisterClass(HINSTANCE hInstance);
BOOL                InitInstance(HINSTANCE, int);
LRESULT CALLBACK    WndProc(HWND, UINT, WPARAM, LPARAM);
LRESULT CALLBACK    About(HWND, UINT, WPARAM, LPARAM);
BOOL InitDDraw( void );
void FreeDDraw( void );

int APIENTRY WinMain(HINSTANCE hInstance,
                     HINSTANCE hPrevInstance,
                     LPSTR     lpCmdLine,
                     int       nCmdShow)
{
     // TODO: Place code here.
    MSG msg;
    HACCEL hAccelTable;

    // Initialize global strings
    LoadString(hInstance, IDS_APP_TITLE, szTitle, MAX_LOADSTRING);
    LoadString(hInstance, IDC_DDHELLO, szWindowClass, MAX_LOADSTRING);
    MyRegisterClass(hInstance);

    // Perform application initialization:
    if (!InitInstance (hInstance, nCmdShow))
    {
        return FALSE;
    }

    hAccelTable = LoadAccelerators(hInstance, (LPCTSTR)IDC_DDHELLO);

    //
    if ( !InitDDraw())
    {
        MessageBox(/*GetActiveWindow()*/hwnd, "Init DirectDraw Error!", "Error", MB_OK );
        FreeDDraw();
        DestroyWindow(/*GetActiveWindow()*/hwnd);
        return FALSE;
    }    // Main message loop:*/

    while (GetMessage(&msg, NULL, 0, 0))
    {
        if (!TranslateAccelerator(msg.hwnd, hAccelTable, &msg))
        {
            TranslateMessage(&msg);
            DispatchMessage(&msg);
        }
    }
    return msg.wParam;
}
//
//  FUNCTION: MyRegisterClass()
//
//  PURPOSE: Registers the window class.
//
//  COMMENTS:
//
//    This function and its usage is only necessary if you want this code
//    to be compatible with Win32 systems prior to the 'RegisterClassEx'
//    function that was added to Windows 95. It is important to call this function
//    so that the application will get 'well formed' small icons associated
//    with it.
//
ATOM MyRegisterClass(HINSTANCE hInstance)
{
    WNDCLASSEX wcex;

    wcex.cbSize = sizeof(WNDCLASSEX);

    wcex.style            = CS_HREDRAW | CS_VREDRAW;
    wcex.lpfnWndProc    = (WNDPROC)WndProc;
    wcex.cbClsExtra        = 0;
    wcex.cbWndExtra        = 0;
    wcex.hInstance        = hInstance;
    wcex.hIcon            = LoadIcon(hInstance, (LPCTSTR)IDI_DDHELLO);
    wcex.hCursor        = LoadCursor(NULL, IDC_ARROW);
    wcex.hbrBackground    = (HBRUSH)(COLOR_WINDOW+1);
    wcex.lpszMenuName    = (LPCSTR)IDC_DDHELLO;
    wcex.lpszClassName    = szWindowClass;
    wcex.hIconSm        = LoadIcon(wcex.hInstance, (LPCTSTR)IDI_SMALL);

    return RegisterClassEx(&wcex);
}

//
//   FUNCTION: InitInstance(HANDLE, int)
//
//   PURPOSE: Saves instance handle and creates main window
//
//   COMMENTS:
//
//        In this function, we save the instance handle in a global variable and
//        create and display the main program window.
//
BOOL InitInstance(HINSTANCE hInstance, int nCmdShow)
{
  // HWND hWnd;

   hInst = hInstance; // Store instance handle in our global variable

   hwnd = CreateWindow(szWindowClass, szTitle, WS_OVERLAPPEDWINDOW,
      CW_USEDEFAULT, 0, CW_USEDEFAULT, 0, NULL, NULL, hInstance, NULL);

   if (!hwnd)
   {
      return FALSE;
   }

   ShowWindow(hwnd, nCmdShow);
   UpdateWindow(hwnd);

   return TRUE;
}

//
//  FUNCTION: WndProc(HWND, unsigned, WORD, LONG)
//
//  PURPOSE:  Processes messages for the main window.
//
//  WM_COMMAND    - process the application menu
//  WM_PAINT    - Paint the main window
//  WM_DESTROY    - post a quit message and return
//
//
LRESULT CALLBACK WndProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    int wmId, wmEvent;
    //PAINTSTRUCT ps;
    //HDC hdc;
    TCHAR szHello[MAX_LOADSTRING];
    LoadString(hInst, IDS_HELLO, szHello, MAX_LOADSTRING);

    switch (message)
    {
        case WM_COMMAND:
            wmId    = LOWORD(wParam);
            wmEvent = HIWORD(wParam);
            // Parse the menu selections:
            switch (wmId)
            {
                case IDM_ABOUT:
                   DialogBox(hInst, (LPCTSTR)IDD_ABOUTBOX, hWnd, (DLGPROC)About);
                   break;
                case IDM_EXIT:
                   DestroyWindow(hWnd);
                   break;
                default:
                   return DefWindowProc(hWnd, message, wParam, lParam);
            }
            break;
        case WM_PAINT:
            InitDDraw();
        case WM_KEYDOWN://key press
            switch( wParam )
            {
                case VK_ESCAPE:
                    PostMessage(/*GetActiveWindow()*/hwnd, WM_CLOSE, 0, 0);
                    break;
            }
            break;
        case WM_DESTROY://
            FreeDDraw();
            PostQuitMessage( 0 );
            break;
        default:
            return DefWindowProc(hWnd, message, wParam, lParam);
   }
   return 0;
}

// Mesage handler for about box.
LRESULT CALLBACK About(HWND hDlg, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
        case WM_INITDIALOG:
                return TRUE;

        case WM_COMMAND:
            if (LOWORD(wParam) == IDOK || LOWORD(wParam) == IDCANCEL)
            {
                EndDialog(hDlg, LOWORD(wParam));
                return TRUE;
            }
            break;

    }
    return FALSE;
}

BOOL InitDDraw(void)
{
    DDSURFACEDESC ddsd;
    HDC hdc;

    //Create DirectCraw Object
    if ( DirectDrawCreate(NULL, &lpDD, NULL ) != DD_OK ) return FALSE;

    //Get Mode
    if ( lpDD->SetCooperativeLevel(/*GetActiveWindow()*/hwnd,DDSCL_NORMAL) != DD_OK)
        return FALSE;

    //Fill Primarysurface
    ddsd.dwSize = sizeof( ddsd );
    ddsd.dwFlags = DDSD_CAPS;
    ddsd.ddsCaps.dwCaps = DDSCAPS_PRIMARYSURFACE;

    if ( lpDD->CreateSurface( &ddsd, &lpDDSPrimary, NULL ) != DD_OK)
        return FALSE;

    RECT Rc;
    GetClientRect(/*GetActiveWindow()*/hwnd,&Rc);
    ddsd.dwFlags = DDSD_CAPS | DDSD_WIDTH | DDSD_HEIGHT;
    ddsd.ddsCaps.dwCaps = DDSCAPS_OFFSCREENPLAIN | DDSCAPS_SYSTEMMEMORY;
    ddsd.dwWidth = Rc.right -Rc.left ;
    ddsd.dwHeight = Rc.bottom -Rc.top ;
    //CopyRect(&lprcBack, &Rc);
    lprcBack.left =0;
    lprcBack.top =0;
    lprcBack.right =300;
    lprcBack.bottom =300;

    if(lpDD->CreateSurface (&ddsd,&lpDDSBackSurf,NULL)!=DD_OK)
        return FALSE;

    lpDD->CreateClipper(0,&lpClipper,NULL);
    //lpClipper->Initialize(lpDD,0);
    lpClipper->SetHWnd(0,/*GetActiveWindow()*/hwnd);
    lpDDSPrimary->SetClipper(lpClipper);

    //Draw Text
    if ( lpDDSPrimary->GetDC(&hdc) != DD_OK) return FALSE;

    SetBkColor( hdc, RGB( 0, 0, 255 ) );
    SetTextColor( hdc, RGB( 255, 255, 0 ) );

    TextOut( hdc, 220, 200, szMsg1, lstrlen(szMsg1));
    TextOut( hdc, 280, 240, szMsg2, lstrlen(szMsg2));

    return TRUE;
}

void FreeDDraw( void )
{
    if( lpDD != NULL )
    {
        if( lpDDSPrimary != NULL )
        {
            lpDDSPrimary->Release();
            lpDDSPrimary = NULL;
        }
        if(lpClipper != NULL)
        {
            lpClipper->Release ();
            lpClipper = NULL;
        }
        lpDD->Release();
        lpDD = NULL;
    }
}
